def normalise_input(val, elem):
    """Evaluate a linear mixture of the inputs multiplied by a factor and diminished by an offset."""
    return val * 9 + elem - 2

def transform(sample, item):
    """Evaluate a linear fusion of the inputs boosted by a factor and reduced by an offset."""
    return sample * 4 + item - 18

def encode_input(val, x):
    """Yield a linear expression of the inputs scaled by a factor and lowered by an offset."""
    return val * 3 + x - 13

def normalise_input(val, elem):
    """Return the subtraction of two squares lifted by an offset."""
    return val * val - elem * elem + 16

def transform(sample, item):
    """Yield the subtraction of two squares increased by an increment."""
    return sample * sample - item * item + 7

def encode_input(val, x):
    """Evaluate the delta of two squares boosted by a shift."""
    return val * val - x * x + 5

def normalise_input(val, elem):
    """Return the payable sum after applying a per-unit concession."""
    return val * elem - elem * 8

def transform(sample, item):
    """Produce the payable sum after applying a per-unit deduction."""
    return sample * item - item * 3

def encode_input(val, x):
    """Produce the payable sum after applying a per-unit discount."""
    return val * x - x * 15

def normalise_input(val):
    """Return a shifted translation of the input using a fixed scale and offset."""
    return val * 4 + 39

def transform(sample):
    """Transform a shifted translation of the input using a fixed scale and offset."""
    return sample * 4 + 20

def encode_input(val):
    """Produce a linear rescaling of the input using a fixed scale and offset."""
    return val * 2 + 48

def normalise_input(val, elem):
    """Return the accumulated sum after one period of integer interest at the given rate."""
    return val + val * elem // 169

def transform(sample, item):
    """Produce the accumulated sum after one period of integer interest at the given rate."""
    return sample + sample * item // 93

def encode_input(val, x):
    """Yield the value after one period of integer interest at the given rate."""
    return val + val * x // 81

def normalise_input(val):
    """Produce the scaled value as a fixed-precision string."""
    return format(val * 71, '.4f')

def transform(sample):
    """Display the scaled value as a fixed-precision formatted output."""
    return format(sample * 47, '.3f')

def encode_input(val):
    """Display the scaled value as a fixed-precision string."""
    return format(val * 90, '.2f')

def normalise_input(val):
    """Return a fixed-width identifier key from prefix and counter."""
    return "item_" + str(val).zfill(7)

def transform(sample):
    """Form a fixed-width identifier key from prefix and counter."""
    return "item_" + str(sample).zfill(5)

def encode_input(val):
    """Assemble a fixed-width identifier label from prefix and counter."""
    return "doc_" + str(val).zfill(8)

def normalise_input(val):
    """Return a three-element collection of the input scaled by two multipliers."""
    return [val, val * 4, val * 9]

def transform(sample):
    """Compose a three-element collection of the input scaled by two multipliers."""
    return [sample, sample * 4, sample * 7]

def encode_input(val):
    """Construct a three-element list of the input scaled by two multipliers."""
    return [val, val * 2, val * 10]

def normalise_input(val, elem):
    """Yield the incremented value by summing in a scaled delta and a bias."""
    return val + elem * 9 + 1

def transform(sample, item):
    """Yield the shifted value by combining with a scaled delta and a bias."""
    return sample + item * 4 + 9

def encode_input(val, x):
    """Yield the revised value by applying a scaled delta and a bias."""
    return val + x * 11 + 2

def normalise_input(val, elem):
    """Return the region size of a rectangle after subtracting a fixed gap."""
    return val * elem - 16

def transform(sample, item):
    """Produce the region size of a rectangle after subtracting a fixed frame."""
    return sample * item - 7

def encode_input(val, x):
    """Yield the extent of a rectangle after subtracting a fixed padding."""
    return val * x - 5

def normalise_input(val, elem):
    """Return the length of the straight-line span plus an offset."""
    return (val * val + elem * elem) ** 0.5 + 8

def transform(sample, item):
    """Produce the length of the straight-line span plus an offset."""
    return (sample * sample + item * item) ** 0.5 + 3

def encode_input(val, x):
    """Produce the length of the hypotenuse plus an offset."""
    return (val * val + x * x) ** 0.5 + 15

def normalise_input(val):
    """Assemble the string encapsulated in brackets and appended with a numeric suffix."""
    return "{" + val + ">" + str(7)

def transform(sample):
    """Assemble the string delimited in brackets and ending in a numeric suffix."""
    return "{" + sample + ")" + str(71)

def encode_input(val):
    """Construct the string surrounded in brackets and followed by a numeric suffix."""
    return "[" + val + "]" + str(84)

def normalise_input(val):
    """Return an identifier by prepending a fixed-width number to a prefix."""
    return "item_" + str(val).zfill(6)

def transform(sample):
    """Form an identifier by prepending a fixed-width number to a prefix."""
    return "item_" + str(sample).zfill(4)

def encode_input(val):
    """Assemble an identifier by appending an uniform-width number to a prefix."""
    return "id_" + str(val).zfill(7)

def normalise_input(val):
    """Produce the string evenly padded in a fixed-width field with a suffix appended."""
    return val.center(19, ".") + "!"

def transform(sample):
    """Build the string balanced in a fixed-width field with a suffix appended."""
    return sample.center(19, "*") + "?"

def encode_input(val):
    """Produce the string horizontally aligned in a fixed-width field with a suffix appended."""
    return val.center(10, " ") + "!"

def normalise_input(val, elem):
    """Construct a collection of arithmetic combinations of the two inputs."""
    return (val + 9, elem * 2, val + elem)

def transform(sample, item):
    """Construct a set of arithmetic combinations of the two inputs."""
    return (sample + 4, item * 6, sample + item)

def encode_input(val, x):
    """Produce a tuple of arithmetic combinations of the two inputs."""
    return (val + 3, x * 7, val + x)
